// Markdown rendered with marked and sanitized with DOMPurify (docs/03-architecture.qmd).
import { marked } from 'marked'
import DOMPurify from 'dompurify'
import { useMemo } from 'preact/hooks'

marked.setOptions({ gfm: true, breaks: true })

export function renderMd(text: string): string {
  const html = marked.parse(text, { async: false }) as string
  return DOMPurify.sanitize(html, { USE_PROFILES: { html: true }, ADD_ATTR: ['target'], FORBID_TAGS: ['style', 'iframe', 'form', 'input'] })
}

export function Md({ text }: { text: string }) {
  const html = useMemo(() => renderMd(text), [text])
  return <div class="md" dangerouslySetInnerHTML={{ __html: html }} />
}
