// Every call to Supabase goes through this module, and it runs only in the frame (AGENTS.md). The anon key is
// public by design; row-level security decides what each person may read and write (docs/05-data-model.qmd).
import { createClient, type Session, type SupabaseClient } from '@supabase/supabase-js'
import type { Anchor, CoverageStatus, MarkKind, MarkRow, PackageRow, SectionRow, BuildToc, TocPage } from '../../shared/types.ts'

// Filled in at build time from .env (the anon/publishable key is public by design; it's still not written into
// the repo's source).
declare const __SUPABASE_URL__: string
declare const __SUPABASE_ANON_KEY__: string
export const SUPABASE_URL = __SUPABASE_URL__
export const SUPABASE_ANON_KEY = __SUPABASE_ANON_KEY__
export const PLATFORM_ORIGIN = location.origin.startsWith('http://localhost') ? location.origin : 'https://subjexts.github.io'

let client: SupabaseClient | null = null
export function sb(): SupabaseClient {
  if (!client) {
    client = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
      auth: { flowType: 'pkce', persistSession: true, autoRefreshToken: true, detectSessionInUrl: false, storageKey: 'yrS4-auth' },
    })
  }
  return client
}

export class ApiError extends Error {
  constructor(msg: string, readonly cause?: unknown) {
    super(msg)
  }
}
function check<T>(r: { data: T | null; error: { message: string } | null }, what: string): T {
  if (r.error) throw new ApiError(`${what}: ${r.error.message}`, r.error)
  return r.data as T
}

// --- session ----------------------------------------------------------------------------------------------------
export async function getSession(): Promise<Session | null> {
  return (await sb().auth.getSession()).data.session
}
export function onAuthChange(cb: (s: Session | null) => void) {
  return sb().auth.onAuthStateChange((_e, s) => cb(s))
}
/** The GitHub sign-in URL for a popup (PKCE; the verifier stays in this frame's storage). */
export async function githubSignInUrl(): Promise<string> {
  const r = await sb().auth.signInWithOAuth({
    provider: 'github',
    options: { skipBrowserRedirect: true, redirectTo: `${PLATFORM_ORIGIN}/auth/callback.html`, scopes: 'read:user user:email' },
  })
  if (r.error || !r.data.url) throw new ApiError(`sign-in: ${r.error?.message || 'no url'}`)
  return r.data.url
}
export async function exchangeCode(code: string) {
  const r = await sb().auth.exchangeCodeForSession(code)
  if (r.error) throw new ApiError(`sign-in: ${r.error.message}`)
  return r.data.session
}
/** Dev only (build log B4): email + password for test accounts while GitHub sign-in isn't registered. */
export async function devSignIn(email: string, password: string) {
  const r = await sb().auth.signInWithPassword({ email, password })
  if (r.error) throw new ApiError(`sign-in: ${r.error.message}`)
  return r.data.session
}
export async function signOut() {
  await sb().auth.signOut()
}

// --- profile ----------------------------------------------------------------------------------------------------
export interface Profile { user_id: string; display_name: string; handle: string | null; role: 'student' | 'instructor' | 'admin' }
export async function myProfile(): Promise<Profile | null> {
  const r = await sb().from('profiles').select('user_id, display_name, handle, role').maybeSingle()
  return check(r, 'profile')
}
export async function updateProfile(p: Partial<Pick<Profile, 'display_name' | 'handle'>>) {
  const s = await getSession()
  if (!s) throw new ApiError('not signed in')
  check(await sb().from('profiles').update(p).eq('user_id', s.user.id), 'profile')
}

// --- packages, sections, builds -----------------------------------------------------------------------------------
export async function packageBySlug(slug: string): Promise<PackageRow | null> {
  const r = await sb().rpc('yrs4_package_by_slug', { s: slug })
  const rows = check(r, 'package') as PackageRow[]
  return rows?.[0] || null
}
export async function sectionBySlug(slug: string): Promise<SectionRow | null> {
  const r = await sb().from('sections').select('*, course:courses(code, title)').eq('slug', slug).maybeSingle()
  return check(r, 'section') as SectionRow | null
}
/** Sections visible to the viewer that use this package (public ones, plus enrolled/staff ones). */
export async function sectionsForPackage(packageId: string): Promise<SectionRow[]> {
  const r = await sb().from('sections').select('*, course:courses(code, title)').contains('packages', [packageId]).order('slug')
  return check(r, 'sections') as SectionRow[]
}
export async function myStaffSectionIds(): Promise<string[]> {
  const s = await getSession()
  if (!s) return []
  const r = await sb().from('section_staff').select('section_id').eq('user_id', s.user.id)
  return (check(r, 'staff') as Array<{ section_id: string }>).map((x) => x.section_id)
}
export interface BuildRow { id: string; source_commit: string | null; built_at: string; toc: BuildToc; page_map: Record<string, { path: string; source?: string }> | null }
export async function latestBuild(packageId: string, withToc = false): Promise<BuildRow | null> {
  const cols = withToc ? 'id, source_commit, built_at, toc, page_map' : 'id, source_commit, built_at'
  const r = await sb().from('package_builds').select(cols).eq('package_id', packageId).order('built_at', { ascending: false }).limit(1).maybeSingle()
  return check(r, 'build') as unknown as BuildRow | null
}
/** The canonical page id for a path, from the latest build (handles previews served from another folder). */
export async function pageForPath(packageId: string, path: string): Promise<string | null> {
  const r = await sb().rpc('yrs4_page_for_path', { pkg: packageId, p: path })
  return (check(r, 'page') as string | null) || null
}
export function tocPage(toc: BuildToc | undefined, page: string): TocPage | undefined {
  return toc?.pages.find((p) => p.page === page)
}

// --- meetings ---------------------------------------------------------------------------------------------------
export interface Meeting { id: string; section_id: string; meets_on: string; title: string | null; note: string | null }
export async function meetingsFor(sectionIds: string[]): Promise<Meeting[]> {
  if (!sectionIds.length) return []
  const r = await sb().from('class_meetings').select('*').in('section_id', sectionIds).order('meets_on', { ascending: false })
  return check(r, 'meetings') as Meeting[]
}
/** The meeting for a section on a date, created if needed (docs/06-coverage.qmd). */
export async function ensureMeeting(sectionId: string, date: string, title?: string): Promise<Meeting> {
  const ex = await sb().from('class_meetings').select('*').eq('section_id', sectionId).eq('meets_on', date).maybeSingle()
  const row = check(ex, 'meeting') as Meeting | null
  if (row) return row
  const r = await sb().from('class_meetings').insert({ section_id: sectionId, meets_on: date, title: title || null }).select('*').single()
  return check(r, 'meeting') as Meeting
}
export async function updateMeeting(id: string, patch: Partial<Pick<Meeting, 'title' | 'note'>>) {
  check(await sb().from('class_meetings').update(patch).eq('id', id), 'meeting')
}

// --- marks ------------------------------------------------------------------------------------------------------
export async function pageMarks(packageId: string, page: string | null, kinds?: MarkKind[]): Promise<MarkRow[]> {
  const r = await sb().rpc('yrs4_page_marks', { pkg: packageId, pg: page, kinds: kinds || null })
  return check(r, 'marks') as MarkRow[]
}
export interface NewMark {
  kind: MarkKind
  package_id: string
  page: string | null
  anchor: Anchor | null
  body?: string | null
  data?: Record<string, unknown>
  build_id?: string | null
}
export async function createMark(m: NewMark, sections: Array<{ section_id: string; meeting_id?: string | null }>): Promise<MarkRow> {
  const s = await getSession()
  if (!s) throw new ApiError('sign in first')
  const ins = await sb().from('marks').insert({ ...m, author_id: s.user.id, data: m.data || {} }).select('*').single()
  const row = check(ins, 'save') as Omit<MarkRow, 'sections'>
  if (sections.length) {
    const r = await sb().from('mark_sections').insert(sections.map((x) => ({ mark_id: row.id, section_id: x.section_id, meeting_id: x.meeting_id || null })))
    if (r.error) {
      await sb().from('marks').delete().eq('id', row.id)
      throw new ApiError(`save: ${r.error.message}`)
    }
  }
  const [full] = await pageMarks(m.package_id, m.page, [m.kind]).then((rows) => rows.filter((x) => x.id === row.id))
  return full
}
export async function updateMark(id: string, patch: { body?: string | null; data?: Record<string, unknown>; status?: string; anchor_current?: Anchor | null }) {
  check(await sb().from('marks').update(patch).eq('id', id), 'update')
}
export async function setCoverageStatus(id: string, data: Record<string, unknown>, status: CoverageStatus) {
  await updateMark(id, { data: { ...data, status } })
}
export async function deleteMark(id: string) {
  check(await sb().from('marks').update({ deleted_at: new Date().toISOString() }).eq('id', id), 'delete')
}
export async function undeleteMark(id: string) {
  check(await sb().from('marks').update({ deleted_at: null }).eq('id', id), 'undo')
}
export async function setMarkSections(id: string, sections: Array<{ section_id: string; meeting_id?: string | null }>) {
  check(await sb().from('mark_sections').delete().eq('mark_id', id), 'sections')
  if (sections.length) check(await sb().from('mark_sections').insert(sections.map((x) => ({ mark_id: id, ...x, meeting_id: x.meeting_id || null }))), 'sections')
}
export async function myNotes(packageId: string): Promise<MarkRow[]> {
  const s = await getSession()
  if (!s) return []
  const rows = await pageMarks(packageId, null, ['author_note'])
  return rows.filter((m) => m.author_id === s.user.id)
}

// --- errors -----------------------------------------------------------------------------------------------------
let reported = 0
export async function reportError(e: { package?: string; page?: string; origin?: string; message: string; stack?: string; version?: string }) {
  if (reported++ > 5) return
  try {
    const s = await getSession()
    await sb().from('client_errors').insert({ ...e, user_agent: navigator.userAgent.slice(0, 300), user_id: s?.user.id || null })
  } catch { /* never throw from the reporter */ }
}

// --- Phase 2: replies, joining, messages, instructor requests ----------------------------------------------------
export interface Reply { id: string; mark_id: string; author_id: string; body: string; data: Record<string, unknown>; created_at: string; author?: { display_name: string } }
export async function replies(markIds: string[]): Promise<Reply[]> {
  if (!markIds.length) return []
  const r = await sb().from('mark_replies').select('*, author:public_profiles(display_name)').in('mark_id', markIds).order('created_at')
  return check(r, 'replies') as Reply[]
}
export async function reply(markId: string, body: string, data: Record<string, unknown> = {}): Promise<Reply> {
  const s = await getSession()
  if (!s) throw new ApiError('sign in first')
  const r = await sb().from('mark_replies').insert({ mark_id: markId, author_id: s.user.id, body, data }).select('*').single()
  return check(r, 'reply') as Reply
}
export async function joinSection(code: string): Promise<string> {
  const r = await sb().rpc('yrs4_join_section', { code })
  return check(r, 'join') as string
}
export async function myEnrollments(): Promise<string[]> {
  const s = await getSession()
  if (!s) return []
  const r = await sb().from('enrollments').select('section_id').eq('user_id', s.user.id)
  return (check(r, 'enrollments') as Array<{ section_id: string }>).map((x) => x.section_id)
}
export async function setJoinCode(sectionId: string, code: string | null) {
  if (code) check(await sb().from('section_join_codes').upsert({ section_id: sectionId, code }), 'join code')
  else check(await sb().from('section_join_codes').delete().eq('section_id', sectionId), 'join code')
}
/** Staff only: the join codes of their sections. */
export async function joinCodes(sectionIds: string[]): Promise<Record<string, string>> {
  if (!sectionIds.length) return {}
  const r = await sb().from('section_join_codes').select('section_id, code').in('section_id', sectionIds)
  return Object.fromEntries((check(r, 'join codes') as Array<{ section_id: string; code: string }>).map((x) => [x.section_id, x.code]))
}
/** Messages the viewer may see on this package (own ones, or those of sections they staff), any page. */
export async function messages(packageId: string): Promise<MarkRow[]> {
  return pageMarks(packageId, null, ['message'])
}
export async function requestInstructor(form: Record<string, unknown>) {
  const s = await getSession()
  if (!s) throw new ApiError('sign in first')
  check(await sb().from('profiles').update({ instructor_request: { ...form, requested_at: new Date().toISOString() } }).eq('user_id', s.user.id), 'request')
}
export async function myProfileFull(): Promise<(Profile & { instructor_request: Record<string, unknown> | null }) | null> {
  const r = await sb().from('profiles').select('user_id, display_name, handle, role, instructor_request').maybeSingle()
  return check(r, 'profile')
}

export async function setSectionAi(sectionId: string, ai: Record<string, unknown>) {
  check(await sb().from('sections').update({ ai }).eq('id', sectionId), 'tutor settings')
}
export async function aiUsage(sectionId: string): Promise<Array<{ month: string; conversations: number; messages: number; cost_usd: number }>> {
  const r = await sb().rpc('yrs4_ai_usage', { s: sectionId })
  return check(r, 'usage') as Array<{ month: string; conversations: number; messages: number; cost_usd: number }>
}
export async function reactionCounts(sectionId: string, packageId: string, page: string): Promise<Array<{ anchor: unknown; emoji: string; label: string; n: number }>> {
  const r = await sb().rpc('yrs4_reaction_counts', { s: sectionId, pkg: packageId, pg: page })
  return check(r, 'activity') as Array<{ anchor: unknown; emoji: string; label: string; n: number }>
}
